pub fn station_by_id(id: u16) -> Option<&'static StationProfile> {
    STATION_PROFILES.iter().find(|station| station.id == id)
}

pub fn zone_pressure_baseline(zone: u8) -> u32 {
    let mut total = 0u32;
    let mut count = 0u32;
    for station in STATION_PROFILES {
        if station.zone == zone {
            total += station.pressure_class as u32;
            count += 1;
        }
    }
    if count == 0 {
        60
    } else {
        total / count
    }
}

pub fn flow_family_score(family: u8, flow: u16) -> u32 {
    let mut score = flow as u32;
    for station in STATION_PROFILES
        .iter()
        .filter(|station| station.family == family)
    {
        score = score.wrapping_add((station.nominal_flow as u32) ^ (station.pressure_class as u32));
    }
    score.rotate_left((family & 15) as u32)
}
